svg.script:
(async () => {
  const status = document.getElementById('status');

  function setStatus(msg) {
    status.textContent = msg;
    console.log(msg);
  }

  try {
    const base = new URL('./', location.href);
    setStatus("Base URL: " + base.href);

    setStatus("Registering service worker…");
    const registration = await navigator.serviceWorker.register(new URL('sw.js', base), {
      scope: base.pathname,
      updateViaCache: 'none'
    });

    const worker = registration.active || registration.installing || registration.waiting;
    if (!worker) throw new Error("Service worker did not start");

    if (worker.state !== 'activated') {
      setStatus("Waiting for worker to activate…");
      await new Promise((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error("Worker timed out")), 10000);

        function check() {
          setStatus("Worker state: " + worker.state);
          if (worker.state === 'activated') {
            clearTimeout(timeout);
            resolve();
          }
          if (worker.state === 'redundant') {
            clearTimeout(timeout);
            reject(new Error("Worker became redundant"));
          }
        }

        worker.addEventListener('statechange', check);
        check();
      });
    }

    setStatus("Worker ready. Loading page…");

    const app = document.getElementById('app');
    app.src = new URL('index.html', base).href;
    app.style.display = 'block';
    status.remove();

  } catch (err) {
    console.error(err);
    setStatus("Failed: " + err.message);
  }
})();
